class FindElements {
    unordered_set<int> seen;

    void recover(TreeNode* node, int val) {
        if (!node) return;
        node->val = val;
        seen.insert(val);
        recover(node->left, 2 * val + 1);
        recover(node->right, 2 * val + 2);
    }
public:
    FindElements(TreeNode* root) {
        recover(root, 0);
    }

    bool find(int target) {
        return seen.count(target) > 0;
    }
};
